#!/usr/bin/env bash
source "$(dirname "$0")/common.sh"
heading 'Paso 16 — Bronze batch → Silver BigQuery'
run_query() { bq --project_id="$PROJECT_ID" --location="$REGION" query --use_legacy_sql=false --maximum_bytes_billed=20971520 "$1"; }
run_query "MERGE \`$PROJECT_ID.$SILVER_DATASET.pedidos\` T USING (SELECT JSON_VALUE(payload_json,'$.order_id') order_id, JSON_VALUE(payload_json,'$.order_line_id') order_line_id, JSON_VALUE(payload_json,'$.customer_id') customer_id, JSON_VALUE(payload_json,'$.store_id') store_id, JSON_VALUE(payload_json,'$.warehouse_id') warehouse_id, JSON_VALUE(payload_json,'$.sku_id') sku_id, SAFE_CAST(JSON_VALUE(payload_json,'$.quantity') AS INT64) quantity, effective_at occurred_at, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.pedidos_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.order_id=S.order_id AND COALESCE(T.order_line_id,'')=COALESCE(S.order_line_id,'') WHEN NOT MATCHED THEN INSERT ROW"
run_query "MERGE \`$PROJECT_ID.$SILVER_DATASET.inventario\` T USING (SELECT CONCAT(batch_id,':',file_id,':',CAST(source_row_number AS STRING)) snapshot_id, JSON_VALUE(payload_json,'$.warehouse_id') warehouse_id, JSON_VALUE(payload_json,'$.store_id') store_id, JSON_VALUE(payload_json,'$.sku_id') sku_id, SAFE_CAST(JSON_VALUE(payload_json,'$.on_hand_qty') AS INT64) on_hand_qty, SAFE_CAST(JSON_VALUE(payload_json,'$.reserved_qty') AS INT64) reserved_qty, effective_at, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.inventario_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.snapshot_id=S.snapshot_id WHEN NOT MATCHED THEN INSERT ROW"
run_query "MERGE \`$PROJECT_ID.$SILVER_DATASET.entregas\` T USING (SELECT JSON_VALUE(payload_json,'$.delivery_id') delivery_id, JSON_VALUE(payload_json,'$.order_id') order_id, JSON_VALUE(payload_json,'$.store_id') store_id, JSON_VALUE(payload_json,'$.region_id') region_id, CAST(NULL AS TIMESTAMP) promised_at, CAST(NULL AS TIMESTAMP) delivered_at, SAFE_CAST(JSON_VALUE(payload_json,'$.delivery_cost') AS NUMERIC) delivery_cost, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.entregas_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.delivery_id=S.delivery_id WHEN NOT MATCHED THEN INSERT ROW"
run_query "MERGE \`$PROJECT_ID.$SILVER_DATASET.telemetria_activos\` T USING (SELECT JSON_VALUE(payload_json,'$.asset_id') asset_id, JSON_VALUE(payload_json,'$.sensor_id') sensor_id, JSON_VALUE(payload_json,'$.warehouse_id') warehouse_id, JSON_VALUE(payload_json,'$.store_id') store_id, JSON_VALUE(payload_json,'$.metric_name') metric_name, SAFE_CAST(JSON_VALUE(payload_json,'$.metric_value') AS FLOAT64) metric_value, JSON_VALUE(payload_json,'$.unit') unit, effective_at occurred_at, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.telemetria_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.asset_id=S.asset_id AND T.sensor_id=S.sensor_id AND T.occurred_at=S.occurred_at WHEN NOT MATCHED THEN INSERT ROW"
printf 'Silver batch verificado para %s\n' "$DEMO_RUN_ID" > "$ROOT/state/$DEMO_RUN_ID/silver_batch_ok.txt"
echo 'OK: Bronze batch curado en Silver'
